// Typed reader for content/lesson-manifest.json (generated by `npm run validate -- --write`).
import { readFileSync } from "node:fs";

export interface WalkerStep {
  id: string;
  screen: string;
  stage: string;
  heading: string | null;
  interaction: { id: string; props: Record<string, unknown> } | null;
}

export interface WalkerLesson {
  id: string;
  title: string;
  status: string;
  fixture: boolean;
  route: string;
  steps: WalkerStep[];
  quiz: { id: string; answer: string; answerLabel?: string }[];
}

export interface WalkerManifest {
  schemaVersion: 1;
  lessons: WalkerLesson[];
}

export function readManifest(): WalkerManifest {
  return JSON.parse(readFileSync("content/lesson-manifest.json", "utf8")) as WalkerManifest;
}

/** Fixtures and every lesson that is `shippable` or `shipped`; drafts are not walked. */
export function walkedLessons(): WalkerLesson[] {
  return readManifest().lessons.filter(
    (l) => l.fixture || l.status === "shippable" || l.status === "shipped",
  );
}
